"""Task-local helper: find and describe SQLite databases in this folder.

This only inspects the local workspace database so the login script can be
written against its actual schema. It performs no writes.
"""
import os
import sqlite3
import sys


def quote_identifier(name: str) -> str:
    return '"' + name.replace('"', '""') + '"'


def main() -> int:
    cwd = os.getcwd()
    print("Working directory:", cwd)
    print("Directory entries:")
    for entry in sorted(os.listdir(cwd)):
        print("  ", entry)

    db_candidates = [
        name
        for name in os.listdir(cwd)
        if os.path.isfile(name)
        and name.lower().endswith((".db", ".sqlite", ".sqlite3", ".sql3"))
    ]

    if not db_candidates:
        print("\nNo SQLite database files found in the current directory.")
        return 0

    for db in db_candidates:
        print(f"\n=== Database: {db} ===")
        try:
            with sqlite3.connect(db) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name, sql FROM sqlite_master "
                    "WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("  (no tables)")
                for table in tables:
                    print(f"TABLE: {table['name']}")
                    print(f"  SQL: {table['sql']}")
                    try:
                        count = cur.execute(
                            f"SELECT COUNT(*) FROM {quote_identifier(table['name'])}"
                        ).fetchone()[0]
                        print(f"  ROW COUNT: {count}")
                        rows = cur.execute(
                            f"SELECT * FROM {quote_identifier(table['name'])} LIMIT 5"
                        ).fetchall()
                        for row in rows:
                            print("  SAMPLE:", dict(row))
                    except sqlite3.Error as exc:
                        print("  ERROR reading table:", exc)
        except sqlite3.Error as exc:
            print("  Error opening database:", exc)

    return 0


if __name__ == "__main__":
    sys.exit(main())

